#!/usr/bin/env python3
"""
Round 136b (culprits), 2 October 2026. Needs round 135b.

Six more ocean pressures, and offshore platforms.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 136b (2 October)\n\nNeeds round 135b. Tiles patch round136b_tiles.py beside it. No app.js?v= bump.\n\n- Six more ocean pressures, each its own row under Every human impact together\n  (asked 2 October: yes to the ocean harms not yet on the map), from the same\n  study (Halpern et al. 2019, KNB, CC0), 2013 and 2003, 0 to 1 as the authors\n  rescaled them: ocean_slr (sea level rise), ocean_light (light at night),\n  ocean_trawling (bottom trawling and dredging: demersal destructive fishing),\n  ocean_bycatch (high and low bycatch, demersal and pelagic), ocean_coastal_people\n  (direct human), ocean_runoff (fertiliser and pesticides; also under\n  Pollution at sea). Tiles ocean_stressors.py finds the files through\n  DataONE's search by name and writes every name it found and what it took to\n  oceans/stressors.build.json: check it after the first run.\n- offshore_platforms: every platform OpenStreetMap maps at sea (man_made =\n  offshore_platform, seamark:type = platform), every tag, coloured by what its\n  tags say (oil, gas, both, wind, not stated); under Oceans and under Oil\n  spills and slicks at sea. Tiles offshore_platforms.py (Overpass, 30-degree\n  slices). Not a register: coverage is as complete as the volunteers' mapping.\n- Not done yet: noise, seagrass and salt marsh loss, sand dredging, ghost\n  gear, shark finning and whaling (sources to be checked).\n\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round136b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 135b" not in h.read_text(encoding="utf-8"):
        sys.exit("round136b: round 135b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round136b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round136b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round136b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
